 /** The environment variable name for one field of a secret. */
 export function envName(path: string, field: string): string {
-  throw new Error("not implemented");
+  if (field === "") throw new RangeError("field must not be empty");
+  const last = path.split("/").pop() ?? "";
+  const name = `${last}_${field}`
+    .toUpperCase()
+    .replace(/[^A-Z0-9]+/g, "_")
+    .replace(/^_+|_+$/g, "");
+  if (name === "") throw new RangeError(`no variable name can be built from ${JSON.stringify(path)} and ${JSON.stringify(field)}`);
+  return /^[0-9]/.test(name) ? `_${name}` : name;
+}
+
+const NAME_PATTERN = /^[A-Z_][A-Z0-9_]*$/;
+const PLAIN_VALUE = /^[A-Za-z0-9_@%+=:,./-]+$/;
+const ESCAPES: Record<string, string> = { "\\": "\\\\", '"': '\\"', $: "\\$", "\n": "\\n", "\r": "\\r" };
+
+function renderValue(value: string): string {
+  if (value === "") return "";
+  if (PLAIN_VALUE.test(value)) return value;
+  return `"${value.replace(/[\\"$\n\r]/g, (c) => ESCAPES[c])}"`;
 }

 /** Render variables as the lines of a dotenv file. */
 export function renderEnvFile(vars: Record<string, string>): string {
-  throw new Error("not implemented");
+  const names = Object.keys(vars).sort();
+  for (const name of names) {
+    if (!NAME_PATTERN.test(name)) throw new RangeError(`invalid variable name: ${JSON.stringify(name)}`);
+  }
+  return names.map((name) => `${name}=${renderValue(vars[name])}\n`).join("");
 }

